input.sparql:
SELECT ?p ?tsid WHERE {
  ?p brick:hasSubComponent <http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02> .
  ?p a brick:Air_TemperatureSensor .
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid . }
}

SELECT ?p ?tsid ?lbl WHERE {
  ?p a <https://brickschema.org/schema/Brick#Zone_Air_Temperature_Sensor> ; rdfs:label ?lbl .
  FILTER(CONTAINS(?lbl, "Perimeter_mid"))
  OPTIONAL { ?p <https://brickschema.org/schema/Brick/ref#TimeseriesReference> ?tsid . }
}

SELECT ?p ?lbl ?ref ?tsid WHERE {
  ?p a <https://brickschema.org/schema/Brick#Zone_Air_Temperature_Sensor> ; rdfs:label ?lbl .
  OPTIONAL { ?p <https://brickschema.org/schema/Brick/ref#hasExternalReference> ?ref . }
  OPTIONAL { ?p <https://brickschema.org/schema/Brick/ref#hasTimeseriesId> ?tsid . }
}
